class DisclosureWidget(forms.Widget):
    template_name = "widgets/disclosure.html"      # consumer overrides the markup
    def __init__(self, expanded=False, attrs=None):
        self.expanded = expanded                   # behaviour/state stays in Python
        super().__init__(attrs)
    def get_context(self, name, value, attrs):
        ctx = super().get_context(name, value, attrs)
        ctx["widget"]["expanded"] = self.expanded  # state handed to the template
        return ctx
